    "text": "我听了一个外国人学汉语的故事，这个故事不太难，你也听听吧。\n一天，罗宾跟他的朋友说，他打算今年放暑假的时候去中国旅游，但他不会说\n汉语，所以他要从现在起，去一个汉语学校学习半年汉语。罗宾很快找到了一个汉\n语学校，他天天晚上去那里学习两个小时。半年很快过去了，他的朋友问他汉语会\n了没有，他说，很简单，学会了。暑假的时候，罗宾按自己的计划去了中国。从中\n国回来以后，他的朋友问他：“你学会了汉语，在中国一定没遇到麻烦吧？”他说：\n“没有。”他的朋友不相信他的话，又问：“真的吗？”“我真的没遇到麻烦，不过，中\n国人遇到了麻烦。”",
