    "text": "我们大学有好几个学生食堂，教学\n楼旁边有一个，宿舍楼旁边有一个，操\n场旁边有一个，图书馆旁边也有一个，\n你想去哪个就去哪个，非常方便。\n这些学生食堂大小不一样，最大的\n有几百个座位，最小的只有几十个座位。\n为了方便学生吃饭，每个学生食堂开门\n的时间也不一样，有的早饭时间、午饭\n时间和晚饭时间开门，有的是白天12个\n小时都开着门，你想什么时候吃饭都可以。\n吃饭的时候，每个食堂的学生都很多，但你不用担心排队问题，\n因为，每个食\n堂都用饭卡。用饭卡买饭速度很快，从你走进食堂挑选饭菜到刷卡，大概只要十几\n分钟。",
