    "kind": "quiz",
    "text": "苏珊和卡琳都是意大利人，苏珊是学生，卡琳在中国的一个意大利公司工作。\n今天她们俩一起去了一家饭馆吃饭。苏珊要了一碗面条，卡琳要了一碗炒饭。苏珊\n用又子，卡琳用筷子。苏珊问卡琳是什么时候学会用筷子的，卡琳说，她在意大利\n的时候就学会了，因为那时候她一到周末就去中国饭馆吃饭。卡琳问苏珊她们大学\n的食堂饭菜怎么样，苏珊说很丰富，每顿饭都有米饭、馒头、包子，还有很多中国\n菜。苏珊还问卡琳，她不会说汉语，在他们公司的食堂怎么买饭，卡琳说，他们吃\n的是自助餐，想吃什么就拿什么，不用担心不会说汉语的问题。",
