    "titleZh": "短文二 鸡蛋4块一斤",
    "kind": "quiz",
    "text": "在我们国家买鸡蛋，一般问多少钱一个，可是在中国不一样，人们习惯问多少\n钱一斤。\n刚来中国的时候，我不知道中国人的这个习惯。有一天，我到一个农贸市场买\n蔬菜、水果和鸡蛋。我问二个卖鸡蛋的人：“请问，鸡蛋怎么卖呀？”我的意思是问\n多少钱一个。可是卖鸡蛋的人以为我问的是多少钱一斤，所以他回答“4块”。我\n想，真够贵的。可是鸡蛋我必须买。我给了那个卖鸡蛋的人 20块钱，请他给我称5\n个鸡蛋。他拿了5个鸡蛋，放在秤上称了称说：“您这是20块，找您18块。”我说：\n“您为什么找我那么多钱？”他说：“4块一斤，5个鸡蛋是半斤，您给我20块，找您\n18块钱。您看对不对？”我看了看，不多也不少，正好18块。",
