    "text": "女：老孙，早上好！\n男：早上好！\n女：你到28层，是吧？\n男：不，我们公司在38层。你们公司呢？\n女：在45层。\n男：电梯太挤了。我常想，要是我们公司在十几层，我每天就爬楼梯。\n女：我也是这么想，可现在怎么办呢？\n男：没有好办法，只好每天坐电梯了。\n女：你看，38层到了。\n男：下次见！\n女：下次见！\n【一）根据对话内容，选择正确答案\n1.这个对话是在哪儿？（B）\nA.汽车上\n2.这个对话是在什么时候？（A）\nA. 早上\n3.男的的公司在多少层？（B）\nA.28 层\nChoose the correct answer according to the conversation.\nB.电梯上\nB. 晚上\nB.38 层\n（二）根据对话内容填空 Fill in the blanks according to the conversation.\n1.老孙，（早上）好！\n2.电梯太（挤）了。\n3.我常想，要是我们公司在十几（层），我每天就爬楼梯。\n4.没有好办法，只好每天坐（电梯）了。\n$10=5-2",
