    "title": "Текст 1 · Что же делать?",
    "titleZh": "短文一 怎么办呢",
    "kind": "quiz",
    "text": "罗卫平他们公司在一座三十层大楼的第十九层，他每天上下班都得坐电梯。\n虽然这座大楼有好几个电梯，但是，上下班的时候，每个电梯都很挤。\n今天早上，他到办公大楼一层的时候，已经差十分钟九点了，他想，要是今天\n迟到了，他这个月就迟到三次了。怎么办呢？他跑到一个排队最短的电梯门口，站\n在了最后边。几分钟以后，电梯下来了，但他没挤上去，电梯门就关上了。他又等\n了三四分钟，电梯又下来了，他想，这趟一定要挤上去，可是这时候，突然有个人\n在他后边推了他一一下，跑进了电梯，还大声喊：“上不来了，等下一趟吧！”然后电\n梯门又关上了。",
