    "title": "Текст 2 · У меня есть хорошая идея.",
    "titleZh": "短文二 我有一个好主意",
    "kind": "quiz",
    "text": "我每天都按时起床，可是今天睡过头了。我起床以后，没刷牙，也没洗脸，背\n上书包就离开了家。来到马路上，打了一辆出租车，上去就跟司机说：“师傅，您能\n开快一点儿吗？”“对不起，在这条马路上开车，最快的速度每小时只能开60公里。”\n司机说。“可是，我八点上课，现在只有几分钟了，怎么办呢？要是迟到了多不好\n意思啊！”我着急地说。“你别着急，我有一个好主意，不知道你愿意不愿意。”司\n机说。“什么好主意呢？”我马上问。司机说：“你要是现在回家睡觉，明天就不会睡\n过头了，也不会迟到了。”",
