    "title": "Текст 1 · У моего телефона села батарея.",
    "titleZh": "短文一 我的手机没电了",
    "kind": "quiz",
    "text": "我和志华是大学同学，上大学的时候关系很好。毕业以后，我们两个人一个在\n北京工作，一个在南京工作，虽然不在一个城市，但经常互相打电话或者发短信。\n可是最近不知道为什么，我给她打电话打不通了，而且每次打的时候都听到里边\n说：“对不起，没有这个电话号码。”怎么回事儿呢？我想，我不会打错，因为我在\n手机里保存了她的手机号码。今天下班以后，我正要离开办公室，我的手机响了，\n我看了看电话号码，以前没见过。是什么人给我打来的呢？我接了电话才知道是志\n华。她告诉我，她换了一个新的电话号码，我想问她最近跟她的男朋友关系怎么样\n了，可是这时候我的手机没电了。",
