    "title": "Текст 2 · Я хочу извиниться",
    "titleZh": "短文二 我想说对不起",
    "kind": "quiz",
    "text": "先生下班回到家，太太马上递过去一杯茶，然后问：“我今天上午给你打了三次\n电话，每次你都关机。怎么回事儿啊？你为什么关机了呢？”“对不起，上午我一\n直在开会，没开机。”先生吗了一口茶说。“下午我又给你扛了三次电话，每次都是\n点线，这又是怎么回事儿啊？”太太又问。“下午我不是打电话，就是接电话，忙极\n了。”先生又喝了一口茶说。“你找我有什么事儿啊？”先生问。“没什么事儿。”太太\n回答。“那你为什么给我打那么多次电话呢？”先生又问。太太开玩笑说：“今天早上\n你去上班的时候，我忘了跟你说再见了，想说对不起。”",
