    "kind": "quiz",
    "text": "我今年虽然73岁了，但也想跟年轻人一样，学电脑，用电脑。可是家里人都\n很忙，谁教我呢？儿子说让孙子每天放学以后教我。\n孙子很快就教我学会了开机、关机和用鼠标，接着又教我学会了上网和发邮\n件。不过，当我第一次给在广州工作的女儿发照片的时候，她却没收到，我孙子\n说，我忘了发附件了。\n学会了上网和发邮件以后，孙子又开始教我学习打字。打字有点儿难，因为我\n的汉语拼音经常打错。有一次，我花了一个星期的时间打完了一篇文章，当我想发\n给一个朋友的时候，却找不到了，我问孙子是怎么回事儿，他说我忘了保存了。",
