    "text": "今天我放学回到家，跟每天一样，写完了作业，就开始教我奶奶学电脑。今天\n我教奶奶学习怎么打开自己的邮箱，因为昨天我已经教了她怎么上网。我告诉奶\n奶，要想打开自己的邮箱，就要先上网，找到自己邮箱用的那个网站，然后输入自\n己的邮箱地址，再输入邮箱的密码，邮箱就打开了。奶奶听了以后说：“我记住了。”\n我说：“那您就开始练习吧。”奶奶按我说的，先输入了网址 www.yahoo.com.cn，雅\n虎网站很快就打开了，接着，她又输入了她的邮箱地址和密码，但因为密码输错\n了，所以打不开。奶奶又输入了一遍，但还是打不开。看来奶奶是不记得密码了。",
