    "text": "今天是我最倒霉的一天。早上睡过头了，跑到马路上打了一辆出租车，到了公\n司已经九，点十分了，迟到了，让经理批评了一额；下午下班走在路上，遇上了大\n雨，没带雨伞，衣服叫大雨淋湿了；晚上吃完晚饭，我想给在杭州出差的先生打个\n电话，告诉他今天遇到的倒霉的事，却发现两岁的儿子正拿着我的手机玩儿呢。我\n说：“好孩子，那是妈妈的手机，给我，我给爸爸打个电话！”儿子听了，一边跑一\n边叫：“爸爸！爸爸！”我跑过去，但手机已经被他摔到了地上，我捡起手机，结果\n发现已经被摔坏了。我想，今天真倒霉！",
