    "kind": "quiz",
    "text": "我一般是在晚上八，点开始写作业，写完以后洗澡，然后上床睡觉。可是今天还\n有一道练习题没做呢，就困了。我看了看表，刚九点多，怎么办呢？明天还要交给\n老师呢。我走到卫生间里洗了洗脸，可是刚坐到椅子上又困了。没办法，我只好脱\n衣服上床，仁躺下就睡着了。十一点多，我突然被电视里足球比赛的声音吵醒了，\n我跟同屋说：“珍妮，你把电视关小点儿声好吗？”她说：“我没看电视，是隔壁的人\n0ciahodi\n在看，我在写作业呢。”我说：“对不起。你还有几道题没做完？”她说：“就剩最后一\n道题了。”我说：“已经十一点多了，别写了，你最好按时睡觉。”她说：“我们老师每\n次留了作业以后都说，一定要按时交作业，没说过要按时睡觉。”",
