    "titleZh": "短文二 你怎么落了一道题呀",
    "kind": "quiz",
    "text": "为顶练习用电脑打汉字，我每次都用电脑写作业，写完以后再用打印机打印出\n来。而每次当我把作业交给老师的时候，老师都说：“你最好用笔写，要是经常用电\n脑写作业，就不会写汉字了。”老师的话很有道理，所以从昨天开始，我就不用电\n脑写作业了。昨天的作业不多，只有综合课的老师留了作业，是做十二课后边的练\n习。因为是用笔写，所以我写得很慢，花了两个多小时才做完。没想到，今天当我\n把作业交给老师的时候，老师却说：“你怎么落了一道题呀？”我说：“没有啊。您不\n是说从练习三到练习五吗？”老师说：“不对，是从练习三到练习六。”",
