    "text": "女：你去医院看病了吗？\n男：去过了。\n女：是感冒吗？\n男：对，我感冒发烧了。\n女：现在怎么样？好点儿了吗？\n男：今天上午已经退烧了，可是还流鼻涕。\n女：感冒挂哪个科？\n男：内科。\n女：挂号的人多吗？排队吗？\n男：排队，看病的人很多。",
