    "titleZh": "对话二 你哪儿不舒服",
    "kind": "quiz",
    "text": "女：你哪儿不舒服？\n男：我从昨天开始肚子疼。\n女：拉肚子吗？\n男：拉，昨天下午拉了五六次，今天上午拉了两次。\n女：你去化验一下吧，化验完了我给你开药。\n（化验完）\n男：大夫，这是化验结果。\n女：我给你开点儿药。\n男：好的。这药一天吃几次啊？\n女：三次，一次吃一片。\n男：是饭前吃还是饭后吃？\n女：饭后吃。",
