    "kind": "quiz",
    "text": "来福大学毕业以后，从山东来到重庆，在一家电脑公司工作。刚才他去了一趟\n银行，过一会儿还要去。为什么呢？事情是这样的：\n来福每个月除了留下生活费以外，剩下的工资都存到了银行，一半存的是活期\n的，一半存的是定期的。几天前，他妈妈从山东打电话来，说他爸爸病了，希望他\n请假回家。他知道，虽然爸爸有保险，但还是有不少事是需要自己花钱的。昨天他\n们公司的经理已经同意他回家了，所以他刚才就去了一趟银行取钱，不过他只取了\n活期的，因沟定期的还没有到期。银行的人说，如果他要取定期的，就要给他们看\n身份证，可是他没带。",
