    "titleZh": "短文一 在北京坐公共汽车",
    "kind": "quiz",
    "text": "在北京坐公共汽车特别方便，无论\n你去什么地方都有公共汽车，而且几分\n钟就有一趟。所以，大部分人上下班、\n买东西、出去玩儿都坐公共汽车。\n在北京坐公共汽车不但方便，而且\n服务很好，汽车每到一站你一般可以听\n到这样两句话：“请前门上车，后门下\n车。”“上车请刷卡，没卡的乘客请买票。”\n这两句话是公共汽车里播放的录音。前\n一句是在汽车到车站的时候播放的，后\n一句话是汽车离开车站的时候播放的。为什么要播放这两句话呢？原因有两个：一\n是因为有的公共汽车是无人售票汽车，二是为了让上下车更快、更安全。",
