    "kind": "quiz",
    "text": "女：我戴上这顶帽子，再围上这条困巾，你看怎么样？\n男：颜色不搭配。\n女：我穿上这件羽绒服，再穿上这条牛仔裤，你看怎么样？\n男：羽绒服太肥了，牛仔裤太瘦了。\n女：我穿上这件T恤，再穿上这条裙子，你看怎么样？\n男：T恤太大了。\n女：真的？\n男：当然。这些东西你又是在商场打折的时候买的吧？\n女：没错儿。\n男：你真的需要这些东西吗？\n女：不太需要，但我一看到很便宜就什么都想买。",
