    "kind": "quiz",
    "text": "我父母一直住在农村，从来没去过大城市，更没有坐过飞机。去年过年的时候\n我回家去接他们。我给他们买了两张往返票，是头等舱的，我自己买的是一张单程\n票，是经济舱的。\n上飞机以前我跟我父母说，飞机上吃的、喝的什么都有，你们什么也不用准\n备。下了飞机以后，我问他们：“头等舱怎么样？”他们说：“非常舒服。服务员一会\n儿问我们想喝什么，一会儿问我们想吃什么，态度好极了。”我又问：“你们吃了什\n么？喝了什么？”他们说：“儿子，你给我们买了那么贵的飞机票，我们不能让你再\n花钱了。”",
