    "kind": "quiz",
    "text": "我和我太太住在哈尔滨，我儿子一家住在香港。从他们搬到香港到现在，我们\n还从来没见过面呢。今年春节我们打算去香港跟他们一起过年，所以我和我太太提\n前半个月就预订了往返飞机票。\n我们上飞机的那天，哈尔滨正下大雪，可是当我们下飞机的时候，香港却是大\n晴天。儿子一家到机场接我们。上三年级的小孙子见到我们说：“爷爷，奶奶，下次\n你们别坐飞机来了。”“你不欢迎我们吗？”我问。“不是，我想坐火车回哈尔滨看你\n们，路过武汉的时候下车去看长江。”我突然想起来了，孙子还没见过长江呢。以\n前我们跟孙子说过，长江经过武汉，将来有时间我一定要带他坐火车到武汉去看长\n江。而坐火车从哈尔滨到香港，正好路过武汉。",
