    "titleZh": "短文一 青年旅馆最便宜",
    "kind": "quiz",
    "text": "出去旅游，住青年旅馆是最便宜的，\n所以，很多年轻人都喜欢住这样的旅馆。\n万东民和他的同学打算一起去桂林旅游，\n他们不想跟旅行社去，想自己去，这几天\n正在网上找合适的青年旅馆，但找了半天\n也没找到满意的，不是位置不好就是没有\n空房间。今天是星期天，他们又在网上看\n广告，找了一上午终于找到了一个比较满\n意的。那个旅馆有单人间，也有双人间。\n全员裔战五十天共迎\n单人间住一个晚上100块，双人间每人\n50块。另外，那个青年旅馆交通也比较方便。他们商量好，马上给那个青年旅馆发\n电子邮件，告诉他们预订什么样的房间、住几天等等。",
