    "title": "Текст 2 · Искал полдня и не нашёл",
    "titleZh": "短文二 打了半天也没找到",
    "kind": "quiz",
    "text": "今天上午，我们旅馆来了两位客人，一个是中国人，一个是澳大利亚人。他们\n问我有没有空房间，我说正好有两个空房间，他们很高兴。我问他们打算住几天，\n他们说住四天。于是，我马上给他们办理手续。当我要看他们的证件的时候，那个\n澳大利亚人马上给我看了他的护照，可是那个中国人找了半天也没找到自己的身份\n证，他非常着急。我说别着急，再想想是不是落在哪儿了，他说可能落在刚才坐的\n出租车里了。我问他要没要出租车的发票，他说没要。我马上给我们那个城市的各\n个出租汽车公司打电话，但打了半天也没找到他坐的那辆出租车。\n〔一）根据短文内容，选择正确答案\nChoose the correct answer according to the text.\n1.“今天”上午来了几个客人？（B）\nA. 一个\nB. 两个\n2.“今天”上午“我”接待的那个外国客人是哪国人？（A）\nA. 澳大利亚人\nB.加拿大人\n3.那个中国人可能把身份证落在哪儿了？（B）\nA.火车里\nB. 出租车里\n（二）根据短文内容，判断正误\n1.“我们”旅馆正好有两个空房间。\n2.他们打算住四天。\n3.“我”马上给他们办理手续。\n4.那个澳大利亚人马上给“我”看了他的护照。\n5.那个中国人忘了带身份证。\nDecide ifthe following statements are true or jalse according to the text.\n（人）\n（人）\n（𠃋）\n（人）\n（×）\n（三）根据短文内容连线\nDo the matching exercise according to the text.\n办\n了\n落在\n出租车里了\n半天\n住宿手续\n房间\n两位客人\n104",
