    "text": "今天早上，汉林起床以后就照镜子、打扮，准备去一个饭店参加同学聚会。\n汉林大学本科和研究生都是在英国上的，毕业以后回到中国工作。从毕业到现\n在已经好几年了，他还从来没跟同学们见过面呢。这次他来英国出差，他的同学听\n说以后都非常高兴。\n.不到十一点，汉林就到了聚会的那个饭店。他想他一定是第一个到的，没想\n到，同学们都提前到了。大家见了面互相握手，互相问候。吃饭的时候，大家举起\n酒杯说：“为我们的友谊干杯！”吃完饭，大家又都抢着付钱，一个男同学说：“我建\n议咱们各付各的，怎么样？”大家说：“好，这个主意不错，就AA 制吧。”",
