    "kind": "quiz",
    "text": "今天中午，我在我们家请客，客人是我的几个朋友。\n为了招待客人，我和我的父母很早就进了厨房，我和爸爸洗菜，妈妈做饭，我\n们一共准备了四个凉菜，六个热菜。中午，朋友们都来了，大家看到一桌子菜，都\n非常惊讶，说：“这么多菜，你们太客气了！”我给每个人都倒了一杯啤酒，说：“大\n家举杯，为我们的友谊干杯！”我父母也说：“吃吧，你们喜欢什么就吃什么，别\n客气。”我的朋友们很快就吃饱了。妈妈看到他们放下了筷子，马上说：“别放下筷子，\n再吃点儿。”我的荷兰朋友说：“谢谢，我饱死了。”大家听了都笑了。他问我们为\n什么笑，我告诉他：“我们不说‘饱死了’，说‘撑死了’。”",
