    "kind": "quiz",
    "text": "我爷爷和奶奶非常喜欢看电视，但两个人喜欢的节目不一样，奶奶要看爱情电\n视剧，爷爷要看足球比赛，所以，他们经常争论，而且看法不一样。\n一天，他们又争论了起来。奶奶可生气了，说：“你都多大年纪了，还每天看小\n伙子踢球，真没意思。”爷爷说：“怎么没意思呢？”奶奶说：“那些运动员为了抢一个\n球，从这边跑到那边，又从那边跑到这边，可是结果呢，不是输了就是赢了。”爷爷\n也很生气，说：“你都多大岁数了，还看爱情电视剧，真没意思。”奶奶说：“怎么没\n意思呢？”爷爷说：“那些电视剧演了一集又一集，都是男人和女人谁爱谁，谁不爱\n谁的事儿，还有别的结果吗？”奶奶说：“当然有，他们不是结婚了就是离婚了，这\n就是结果！”",
