    "text": "最近，马文经常接到偏壁憋女士的电话，说马文唱歌影响了她休息。\n怎么回事儿呢？原来马文准备考北京中央音乐学院，每天都在家里练习唱歌。\n为什么要在家里练习呢？因为她每天上班，没时间练习，只能下班以后练习，可是\n下班回到家已经很晚了。为了不影响赵女士休息，马文一般都是一吃完晚饭就开\n始练习，而且只唱一会儿。今天马文吃完晚饭又准备唱了，唱以前还把窗户都关上\n了。可是，她的声音还是打扰了隔壁的赵女士。赵女士可生气了，她在电话里说：\n“都几点了，你还在唱歌，让不让人休息了！如果你再唱，我马上打110报警。”马\n文刚想说现在还不到睡觉的时间呢；可是赵女士已经把电话柱上了。",
