    "text": "亲爱的妈妈：\n您好！下个月15号就是您的生日了，我给您买了生日礼物，今天给您寄去。\n我给您买的是一条丝绸裙子和一条围巾，都是您最喜欢的灰色。您收到后给我回一\n封电子邮件吧。\n妈妈，您前几天给我寄来的生日贺卡我收到了，谢谢您！您问我生日过得怎么\n样，您放心吧，我过得特别高兴。生日前几天，老师给我写了生日贺卡。老师在贺\n卡上表扬我，说我学习进步很快。生日那天，我请我们班的同学来参加了我的生日\n聚会，热闹极了，我们还一起吃了生日蛋糕呢。\n乌鲁木齐现在已经很冷了吧？您和爸爸一定要注意身体。\n好了，就写到这儿吧，请代我问爷爷奶奶好。\n祝您生日快乐！\n您的女儿：阿依古丽\n6月12日杭州",
