    "kind": "quiz",
    "text": "圣诞节和新年就要到了，今天我给朋友们圣了很多贺卡。回到家以后，我把贺\n卡放在桌子上，就去厨房做晚饭乃，打算吃完晚饭以后再写贺卡。\n晚饭还没有做完，我先生就下班回来了。他一进门看到桌子上的贺卡就大声\n喊：“亲爱的，我在下班的路上，看到街上和很多商店门口都挂上了红灯笼我想，\n应该给朋友们室贺卡了，没想到他们先给我寄来了。”我咗了在厨房里大声说：“好\n了，别开玩笑了，那些贺卡是我刚买回来的。你先给咱们大学同学每人写一张贺卡\n吧，写完以后再写一封信，代我向他们问好，祝他们圣诞节快乐，新年快乐。”",
