    "text": "今天，香草收到了上海中医药大学录取她的信，非常高兴。她的老师和同学见\n了她都说：“祝贺你！”\n香草是越南学生，来上海已经五六年了，她先在一所大学进修了两年汉语，然\n后又转学到另外一所大学读了四年本科。香草学习非常努力，上课从来不迟到，而\n且期中考试和期末考试的成绩都在90分以上。他们大学为了鼓励她，每个学期都\n给她奖学金。这些奖学金解决了她的学费和生活费的问题。今年她终于大学毕业\n了，毕业以前她参加了HSK 考试，还申请了到上海中医药大学学习针灸。\n香草对针灸最感兴趣，她下决心一定要努力学习，毕业以后回到越南，当一个\n中医大夫。",
